import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function StudentProfile() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [formData, setFormData] = useState({
    nom: '',
    email: ''
  });
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchProfile();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      setLoading(true);
      setError('');
      console.log('🔄 Chargement du profil étudiant...');
      
      const response = await api.get('/student/profile');
      console.log('✅ Réponse API:', response.data);
      
      if (response.data.success) {
        setProfile(response.data.profile);
        setFormData({
          nom: response.data.profile.nom,
          email: response.data.profile.email
        });
      } else {
        throw new Error(response.data.message || 'Erreur inconnue');
      }
    } catch (error) {
      console.error('❌ Erreur chargement profil:', error);
      const errorMsg = error.response?.data?.message || error.message || 'Erreur lors du chargement du profil';
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    navigate('/dashboard-student');
  };

  const handleEdit = () => {
    setEditing(true);
  };

  const handleCancel = () => {
    setEditing(false);
    setFormData({
      nom: profile.nom,
      email: profile.email
    });
    setMessage('');
    setError('');
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setError('');
      const response = await api.put('/student/profile', formData);
      
      if (response.data.success) {
        setProfile(response.data.profile);
        setEditing(false);
        setMessage('Profil mis à jour avec succès!');
        
        // Mettre à jour les données dans le localStorage
        const userData = JSON.parse(localStorage.getItem('user'));
        const updatedUser = { ...userData, nom: formData.nom, email: formData.email };
        localStorage.setItem('user', JSON.stringify(updatedUser));
      } else {
        throw new Error(response.data.message || 'Erreur inconnue');
      }
    } catch (error) {
      console.error('❌ Erreur mise à jour profil:', error);
      setError(error.response?.data?.message || 'Erreur lors de la mise à jour du profil');
    }
  };

  const handleChangePassword = () => {
    alert('Fonctionnalité de changement de mot de passe à venir!');
  };

  // Styles (gardez les mêmes styles que précédemment)
  const styles = {
    container: {
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'Arial, sans-serif'
    },
    header: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '1rem 2rem',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      borderBottom: '1px solid rgba(255, 255, 255, 0.2)'
    },
    backButton: {
      background: 'none',
      border: '2px solid #667eea',
      color: '#667eea',
      padding: '0.5rem 1rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    title: {
      color: '#2d3748',
      margin: 0
    },
    headerActions: {
      display: 'flex',
      alignItems: 'center',
      gap: '1rem'
    },
    roleBadge: {
      background: 'linear-gradient(135deg, #667eea, #764ba2)',
      color: 'white',
      padding: '0.5rem 1rem',
      borderRadius: '20px',
      fontSize: '0.8rem',
      fontWeight: 'bold'
    },
    main: {
      maxWidth: '1200px',
      margin: '0 auto',
      padding: '2rem'
    },
    successAlert: {
      background: '#d4edda',
      color: '#155724',
      padding: '1rem',
      borderRadius: '8px',
      marginBottom: '1rem',
      border: '1px solid #c3e6cb'
    },
    errorAlert: {
      background: '#f8d7da',
      color: '#721c24',
      padding: '1rem',
      borderRadius: '8px',
      marginBottom: '1rem',
      border: '1px solid #f5c6cb'
    },
    profileGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))',
      gap: '2rem'
    },
    infoCard: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
      gridColumn: '1 / -1'
    },
    statsCard: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
    },
    securityCard: {
      background: 'rgba(255, 255, 255, 0.95)',
      padding: '2rem',
      borderRadius: '15px',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)'
    },
    cardHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '2rem'
    },
    cardTitle: {
      color: '#2d3748',
      margin: 0
    },
    editButton: {
      background: 'linear-gradient(135deg, #667eea, #764ba2)',
      color: 'white',
      border: 'none',
      padding: '0.75rem 1.5rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    form: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1.5rem'
    },
    formGroup: {
      display: 'flex',
      flexDirection: 'column',
      gap: '0.5rem'
    },
    label: {
      fontWeight: '600',
      color: '#4a5568'
    },
    input: {
      padding: '0.75rem',
      border: '2px solid #e2e8f0',
      borderRadius: '8px',
      fontSize: '1rem',
      transition: 'border-color 0.3s ease'
    },
    formActions: {
      display: 'flex',
      gap: '1rem',
      marginTop: '1rem'
    },
    saveButton: {
      background: '#48bb78',
      color: 'white',
      border: 'none',
      padding: '0.75rem 1.5rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    cancelButton: {
      background: '#e53e3e',
      color: 'white',
      border: 'none',
      padding: '0.75rem 1.5rem',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    profileInfo: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1rem'
    },
    infoItem: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '0.75rem 0',
      borderBottom: '1px solid #e2e8f0'
    },
    roleText: {
      background: '#667eea',
      color: 'white',
      padding: '0.25rem 0.75rem',
      borderRadius: '15px',
      fontSize: '0.8rem',
      fontWeight: '600'
    },
    statsGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
      gap: '1rem'
    },
    statItem: {
      textAlign: 'center',
      padding: '1rem',
      background: 'rgba(102, 126, 234, 0.1)',
      borderRadius: '10px'
    },
    statNumber: {
      fontSize: '1.5rem',
      fontWeight: 'bold',
      color: '#667eea',
      marginBottom: '0.5rem'
    },
    statLabel: {
      fontSize: '0.8rem',
      color: '#718096'
    },
    securityInfo: {
      display: 'flex',
      flexDirection: 'column',
      gap: '1rem'
    },
    securityItem: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '1rem',
      background: 'rgba(102, 126, 234, 0.05)',
      borderRadius: '8px'
    },
    securityLabel: {
      fontWeight: '600',
      color: '#4a5568'
    },
    securityStatus: {
      color: '#718096'
    },
    securityButton: {
      background: 'none',
      border: '2px solid #667eea',
      color: '#667eea',
      padding: '0.5rem 1rem',
      borderRadius: '6px',
      cursor: 'pointer',
      fontWeight: '600'
    },
    loadingContainer: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white'
    },
    spinner: {
      width: '50px',
      height: '50px',
      border: '4px solid rgba(255, 255, 255, 0.3)',
      borderLeft: '4px solid white',
      borderRadius: '50%',
      animation: 'spin 1s linear infinite',
      marginBottom: '1rem'
    }
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement de votre profil...</p>
      </div>
    );
  }

  if (!profile) {
    return (
      <div style={styles.container}>
        <div style={styles.errorAlert}>
          {error || 'Impossible de charger votre profil'}
          <button onClick={fetchProfile} style={{ marginLeft: '1rem', padding: '0.5rem 1rem' }}>
            🔄 Réessayer
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <button onClick={handleBack} style={styles.backButton}>
          ← Retour au Dashboard
        </button>
        <h1 style={styles.title}>Mon Profil</h1>
        <div style={styles.headerActions}>
          <span style={styles.roleBadge}>ÉTUDIANT</span>
        </div>
      </header>

      <main style={styles.main}>
        {message && (
          <div style={styles.successAlert}>
            {message}
          </div>
        )}

        {error && (
          <div style={styles.errorAlert}>
            {error}
          </div>
        )}

        <div style={styles.profileGrid}>
          {/* Carte d'information */}
          <div style={styles.infoCard}>
            <div style={styles.cardHeader}>
              <h2 style={styles.cardTitle}>Informations Personnelles</h2>
              {!editing && (
                <button onClick={handleEdit} style={styles.editButton}>
                  ✏️ Modifier
                </button>
              )}
            </div>

            {editing ? (
              <form onSubmit={handleSubmit} style={styles.form}>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Nom complet</label>
                  <input
                    type="text"
                    name="nom"
                    value={formData.nom}
                    onChange={handleChange}
                    style={styles.input}
                    required
                  />
                </div>

                <div style={styles.formGroup}>
                  <label style={styles.label}>Email</label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    style={styles.input}
                    required
                  />
                </div>

                <div style={styles.formActions}>
                  <button type="submit" style={styles.saveButton}>
                    💾 Enregistrer
                  </button>
                  <button type="button" onClick={handleCancel} style={styles.cancelButton}>
                    ❌ Annuler
                  </button>
                </div>
              </form>
            ) : (
              <div style={styles.profileInfo}>
                <div style={styles.infoItem}>
                  <strong>Nom complet:</strong> {profile.nom}
                </div>
                <div style={styles.infoItem}>
                  <strong>Email:</strong> {profile.email}
                </div>
                <div style={styles.infoItem}>
                  <strong>Rôle:</strong> 
                  <span style={styles.roleText}>Étudiant</span>
                </div>
                <div style={styles.infoItem}>
                  <strong>Classe:</strong> {profile.class_name || 'Non assignée'}
                </div>
                <div style={styles.infoItem}>
                  <strong>Niveau:</strong> {profile.class_niveau || 'Non spécifié'}
                </div>
                <div style={styles.infoItem}>
                  <strong>Promotion:</strong> {profile.promotion || '2023-2024'}
                </div>
                <div style={styles.infoItem}>
                  <strong>ID Étudiant:</strong> {profile.id}
                </div>
              </div>
            )}
          </div>

          {/* Carte de statistiques */}
          <div style={styles.statsCard}>
            <h2 style={styles.cardTitle}>Statistiques</h2>
            <div style={styles.statsGrid}>
              <div style={styles.statItem}>
                <div style={styles.statNumber}>6</div>
                <div style={styles.statLabel}>Cours suivis</div>
              </div>
              <div style={styles.statItem}>
                <div style={styles.statNumber}>12</div>
                <div style={styles.statLabel}>Devoirs</div>
              </div>
              <div style={styles.statItem}>
                <div style={styles.statNumber}>14.5</div>
                <div style={styles.statLabel}>Moyenne</div>
              </div>
              <div style={styles.statItem}>
                <div style={styles.statNumber}>85%</div>
                <div style={styles.statLabel}>Assiduité</div>
              </div>
            </div>
          </div>

          {/* Carte de sécurité */}
          <div style={styles.securityCard}>
            <h2 style={styles.cardTitle}>Sécurité</h2>
            <div style={styles.securityInfo}>
              <div style={styles.securityItem}>
                <span style={styles.securityLabel}>Mot de passe</span>
                <span style={styles.securityStatus}>••••••••</span>
                <button onClick={handleChangePassword} style={styles.securityButton}>
                  Changer
                </button>
              </div>
              <div style={styles.securityItem}>
                <span style={styles.securityLabel}>Dernière connexion</span>
                <span style={styles.securityStatus}>Aujourd'hui</span>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default StudentProfile;
